#!/usr/bin/env bash
set -euo pipefail

# Estimate data/model-aware temperatures from SASRec checkpoints generated by
# run_main_benchmark_grid.sh. Only GPU 0 and GPU 1 are used by default.

ROOT="${ROOT:-$(git rev-parse --show-toplevel 2>/dev/null || pwd)}"
CONDA_SH="${CONDA_SH:-/home/ssh_user/miniconda3/etc/profile.d/conda.sh}"
CONDA_ENV="${CONDA_ENV:-recbole}"
SEED="${SEED:-2025}"

DATASETS_STR="${DATASETS_STR:-Beauty Sports Toys Yelp-S3Rec ML-1M LastFM-S3Rec}"
HIDDEN_SIZES_STR="${HIDDEN_SIZES_STR:-64 256}"
GPUS_STR="${GPUS_STR:-0 1}"

DEFAULT_MAX_LEN="${DEFAULT_MAX_LEN:-50}"
ML1M_MAX_LEN="${ML1M_MAX_LEN:-50}"
LASTFM_MAX_LEN="${LASTFM_MAX_LEN:-200}"
EVAL_BATCH_SIZE="${EVAL_BATCH_SIZE:-512}"
SAMPLE_ITEMS="${SAMPLE_ITEMS:-1024}"
MAX_BATCHES="${MAX_BATCHES:-}"
SPLIT="${SPLIT:-valid}"

TAG="${TAG:-main_benchmark_grid}"
OUT_DIR="${OUT_DIR:-$ROOT/analysis_results/temperature_calibration}"
TASK_FILE="$OUT_DIR/tasks.tsv"

mkdir -p "$OUT_DIR/logs"
cd "$ROOT"

if [ -f "$CONDA_SH" ]; then
  # shellcheck source=/dev/null
  source "$CONDA_SH"
else
  echo "WARN: CONDA_SH not found: $CONDA_SH" | tee -a "$OUT_DIR/master.log"
fi

max_len_for_dataset() {
  case "$1" in
    ML-1M) echo "$ML1M_MAX_LEN" ;;
    LastFM-S3Rec) echo "$LASTFM_MAX_LEN" ;;
    *) echo "$DEFAULT_MAX_LEN" ;;
  esac
}

inner_size_for_hidden() {
  echo $(( "$1" * 4 ))
}

latest_checkpoint() {
  local run_name="$1"
  find "$ROOT/ckpt/$TAG/$run_name" -maxdepth 1 -name "*.pth" -type f 2>/dev/null | sort | tail -n 1
}

build_tasks() {
  : > "$TASK_FILE"
  for hidden_size in $HIDDEN_SIZES_STR; do
    inner_size="$(inner_size_for_hidden "$hidden_size")"
    for dataset in $DATASETS_STR; do
      max_len="$(max_len_for_dataset "$dataset")"
      run_name="${dataset}_SASRec_h${hidden_size}_len${max_len}"
      ckpt="$(latest_checkpoint "$run_name")"
      if [ -z "$ckpt" ]; then
        echo "WARN: missing checkpoint for $run_name" | tee -a "$OUT_DIR/master.log"
        continue
      fi
      printf "%s\t%s\t%s\t%s\t%s\t%s\n" \
        "$run_name" "$dataset" "$hidden_size" "$max_len" "$inner_size" "$ckpt" >> "$TASK_FILE"
    done
  done
}

run_task() {
  local gpu="$1"
  local run_name="$2"
  local dataset="$3"
  local hidden_size="$4"
  local max_len="$5"
  local inner_size="$6"
  local ckpt="$7"
  local out_csv="$OUT_DIR/${run_name}.csv"
  local log_file="$OUT_DIR/logs/${run_name}.log"

  if [ -s "$out_csv" ]; then
    echo "[$(date '+%F %T')] SKIP $run_name" | tee -a "$OUT_DIR/master.log"
    return 0
  fi

  echo "[$(date '+%F %T')] START $run_name gpu=$gpu" | tee -a "$OUT_DIR/master.log"
  extra_args=()
  if [ -n "$MAX_BATCHES" ]; then
    extra_args+=(--max_batches "$MAX_BATCHES")
  fi
  conda run --no-capture-output -n "$CONDA_ENV" python experiments/cross_dataset/analyze_temperature_calibration.py \
    --dataset "$dataset" \
    --gpu_id "$gpu" \
    --seed "$SEED" \
    --hidden_size "$hidden_size" \
    --inner_size "$inner_size" \
    --max_item_list_length "$max_len" \
    --eval_batch_size "$EVAL_BATCH_SIZE" \
    --sample_items "$SAMPLE_ITEMS" \
    --split "$SPLIT" \
    --checkpoint "$ckpt" \
    --output "$out_csv" \
    "${extra_args[@]}" \
    > "$log_file" 2>&1
  echo "[$(date '+%F %T')] DONE $run_name" | tee -a "$OUT_DIR/master.log"
}

worker() {
  local gpu="$1"
  local shard="$2"
  local shards="$3"
  local index=0

  while IFS=$'\t' read -r run_name dataset hidden_size max_len inner_size ckpt; do
    if [ $(( index % shards )) -eq "$shard" ]; then
      run_task "$gpu" "$run_name" "$dataset" "$hidden_size" "$max_len" "$inner_size" "$ckpt"
    fi
    index=$(( index + 1 ))
  done < "$TASK_FILE"
}

build_tasks
mapfile -t GPUS < <(printf "%s\n" $GPUS_STR)
if [ "${#GPUS[@]}" -eq 0 ] || [ "${#GPUS[@]}" -gt 2 ]; then
  echo "ERROR: GPUS_STR must contain one or two GPUs, e.g. '0 1'." >&2
  exit 1
fi

echo "[$(date '+%F %T')] ROOT=$ROOT" | tee -a "$OUT_DIR/master.log"
echo "[$(date '+%F %T')] tasks=$(wc -l < "$TASK_FILE") gpus=${GPUS[*]}" | tee -a "$OUT_DIR/master.log"

for shard in "${!GPUS[@]}"; do
  worker "${GPUS[$shard]}" "$shard" "${#GPUS[@]}" &
  echo $! > "$OUT_DIR/worker_gpu${GPUS[$shard]}.pid"
done

wait
echo "[$(date '+%F %T')] ALL_DONE" | tee -a "$OUT_DIR/master.log"
